1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import type { SftpServer } from "../lib/sftp";
4	import {
5	  withServerSsh,
6	  exec,
7	  execInput,
8	  assertDomain,
9	  assertPhp,
10	  assertPath,
11	  shellQuote,
12	  pkgInstallPrefix,
13	  SETUP_TIMEOUT_MS,
14	  INSTALL_TIMEOUT_MS,
15	  QUICK_TIMEOUT_MS,
16	} from "../lib/ssh-exec";
17	import { verifyServing, probeTls } from "../lib/http-probe";
18	import { classifyCertbotOutcome, websiteSslVerdict } from "../lib/ssl-verify";
19	import type { Job } from "@prisma/client";
20	
21	/**
22	 * Control-panel WEBSITE_* handlers.
23	 *
24	 * Registered in worker/index.ts:
25	 *   WEBSITE_CREATE: websiteCreate,
26	 *   WEBSITE_DELETE: websiteDelete,
27	 *   WEBSITE_TOGGLE: websiteToggle,
28	 *   WEBSITE_SSL:    websiteSsl,
29	 *
30	 * Ownership + validation happen at enqueue time (lib/actions-websites.ts); these
31	 * trust `payload.websiteId` but STILL re-validate every value against the strict
32	 * allowlist in lib/ssh-exec before it can reach a shell.
33	 *
34	 * SANDBOX (staging): no SSH — statuses flip with synthetic success, exactly like
35	 * every other worker feature. On prod the real nginx/php/certbot work runs only
36	 * when ENABLE_REAL_CPANEL === "1" (belt-and-suspenders, mirroring worker/ssl.ts);
37	 * otherwise it also takes the simulated-success branch so a fresh prod box can't
38	 * be mutated until the operator explicitly enables it.
39	 */
40	
41	const REAL = !SANDBOX && process.env.ENABLE_REAL_CPANEL === "1";
42	
43	async function notify(userId: string, title: string, body?: string, href?: string) {
44	  try {
45	    await db.notification.create({ data: { userId, title, body, href } });
46	  } catch (e) {
47	    console.error("[cpanel/web] notify failed", e);
48	  }
49	}
