51	async function loadSite(job: Job) {
52	  const p = (job.payload ?? {}) as { websiteId?: string };
53	  if (!p.websiteId) throw new Error("website job: missing websiteId");
54	  const site = await db.website.findUnique({ where: { id: p.websiteId } });
55	  if (!site) throw new Error(`Website ${p.websiteId} not found`);
56	  return site;
57	}
