59	/** Load exactly the SSH fields for a server (mirrors lib/sftp usage). */
60	export async function sshServer(serverId: string): Promise<SftpServer> {
61	  const s = await db.server.findUnique({
62	    where: { id: serverId },
63	    select: {
64	      id: true,
65	      rootPassword: true,
66	      rootPasswordEnc: true,
67	      sshPort: true,
68	      dedicatedIp: { select: { address: true } },
69	    },
70	  });
71	  if (!s) throw new Error(`Server ${serverId} not found`);
72	  return s as SftpServer;
73	}
