75	/** Render an nginx server block. All values are allowlist-validated by callers. */
76	export function nginxVhost(domain: string, docRoot: string, phpVersion: string | null): string {
77	  const phpBlock = phpVersion
78	    ? `
79	    location ~ \\.php$ {
80	        include snippets/fastcgi-php.conf;
81	        fastcgi_pass unix:/run/php/php${phpVersion}-fpm.sock;
82	    }
83	`
84	    : "";
85	  return `# Managed by Nxeon control panel — do not edit by hand.
86	server {
87	    listen 80;
88	    listen [::]:80;
89	    server_name ${domain};
90	    root ${docRoot};
91	    index index.php index.html index.htm;
92	
93	    location / {
94	        try_files $uri $uri/ /index.php?$query_string;
95	    }
96	${phpBlock}
97	    access_log /var/log/nginx/${domain}.access.log;
98	    error_log /var/log/nginx/${domain}.error.log;
99	}
100	`;
101	}
102	
103	export async function ensureNginx(conn: import("ssh2").Client): Promise<void> {
104	  const have = await exec(conn, "command -v nginx >/dev/null 2>&1 && echo yes || echo no", QUICK_TIMEOUT_MS);
105	  if (have.stdout.trim() !== "yes") {
106	    const prefix = await pkgInstallPrefix(conn);
107	    const inst = await exec(conn, `${prefix} nginx`, INSTALL_TIMEOUT_MS);
108	    if (inst.code !== 0) throw new Error(`nginx install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
109	  }
110	  // Ensure the sites-available/enabled layout exists (Debian/Ubuntu default).
111	  await exec(conn, "mkdir -p /etc/nginx/sites-available /etc/nginx/sites-enabled", SETUP_TIMEOUT_MS);
112	}
113	
114	export async function ensurePhpFpm(conn: import("ssh2").Client, phpVersion: string): Promise<void> {
115	  assertPhp(phpVersion);
116	  const svc = `php${phpVersion}-fpm`;
117	  const have = await exec(conn, `systemctl status ${shellQuote(svc)} >/dev/null 2>&1 && echo yes || echo no`, QUICK_TIMEOUT_MS);
118	  if (have.stdout.trim() === "yes") return;
119	  const prefix = await pkgInstallPrefix(conn);
120	  // php{ver}-fpm + the common extensions apps need.
121	  const inst = await exec(
122	    conn,
123	    `${prefix} php${phpVersion}-fpm php${phpVersion}-mysql php${phpVersion}-cli php${phpVersion}-curl php${phpVersion}-gd php${phpVersion}-mbstring php${phpVersion}-xml`,
124	    INSTALL_TIMEOUT_MS
125	  );
126	  if (inst.code !== 0) throw new Error(`php-fpm install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
127	  await exec(conn, `systemctl enable --now ${shellQuote(svc)}`, SETUP_TIMEOUT_MS);
128	}
129	
130	/**
131	 * Reload nginx, and confirm it is actually running afterwards.
132	 *
133	 * `nginx -t` was already checked; the RELOAD's exit code was discarded (M7 #4),
134	 * so a reload that failed — or a restart that left the daemon dead — read as a
135	 * successful configuration change. A dead nginx takes down every OTHER site on
136	 * the box too, which is why this is checked rather than hoped for.
137	 */
138	export async function reloadNginx(conn: import("ssh2").Client): Promise<void> {
139	  const test = await exec(conn, "nginx -t", SETUP_TIMEOUT_MS);
140	  if (test.code !== 0) throw new Error(`nginx config test failed: ${(test.stderr || test.stdout).trim().slice(0, 200)}`);
141	  const r = await exec(conn, "systemctl reload nginx || systemctl restart nginx", SETUP_TIMEOUT_MS);
142	  const active = await exec(conn, "systemctl is-active nginx 2>/dev/null", QUICK_TIMEOUT_MS);
143	  const state = active.stdout.trim();
144	  if (state !== "active") {
145	    throw new Error(
146	      `nginx is "${state || "not running"}" after the reload (systemctl exited ${r.code}), so no site on this ` +
147	        `server is being served. Diagnose with: systemctl status nginx ; journalctl -u nginx -n 50`
148	    );
149	  }
150	}
