154	export async function websiteCreate(job: Job): Promise<void> {
155	  const site = await loadSite(job);
156	  let proof = "not verified";
157	  try {
158	    // Simulation is a SANDBOX affordance and MUST NEVER run in production.
159	    // Copied from the guard at the end of `sslIssue` in worker/ssl.ts, which
160	    // this file's header claims to mirror and did not. Without it, a production
161	    // box that lost ENABLE_REAL_CPANEL writes ACTIVE and tells the customer
162	    // "Your nginx site is configured and serving" having touched nothing — and
163	    // that ACTIVE is what `requestWebsiteSsl` gates on, so certbot HTTP-01 would
164	    // then be offered for a vhost that does not exist.
165	    if (!REAL && !SANDBOX) {
166	      throw new Error(
167	        "Website provisioning is switched off on this server (ENABLE_REAL_CPANEL is not set), so no nginx " +
168	          "vhost, document root or index page was created on your VM. Nothing is being served — this site " +
169	          "is NOT live. Ask support to enable real control-panel provisioning."
170	      );
171	    }
172	
173	    if (REAL) {
174	      assertDomain(site.domain);
175	      assertPath(site.docRoot);
176	      if (site.phpVersion) assertPhp(site.phpVersion);
177	      const server = await sshServer(site.serverId);
178	      const conf = `/etc/nginx/sites-available/${site.domain}.conf`;
179	      const link = `/etc/nginx/sites-enabled/${site.domain}.conf`;
180	      await withServerSsh(server, async (conn) => {
181	        await ensureNginx(conn);
182	        if (site.phpVersion) await ensurePhpFpm(conn, site.phpVersion);
183	        // Docroot + a friendly placeholder index.
184	        await exec(conn, `mkdir -p ${shellQuote(site.docRoot)} && chown -R www-data:www-data ${shellQuote(site.docRoot)} 2>/dev/null || true`, SETUP_TIMEOUT_MS);
185	        await execInput(
186	          conn,
187	          `cat > ${shellQuote(site.docRoot + "/index.html")}`,
188	          `<!doctype html><meta charset="utf-8"><title>${site.domain}</title><h1>${site.domain}</h1><p>Your Nxeon-hosted site is live.</p>\n`,
189	          SETUP_TIMEOUT_MS
190	        );
191	        // Write the vhost via STDIN (never as an argv token), enable, reload.
192	        await execInput(conn, `cat > ${shellQuote(conf)}`, nginxVhost(site.domain, site.docRoot, site.phpVersion), SETUP_TIMEOUT_MS);
193	        if (site.enabled) {
194	          await exec(conn, `ln -sf ${shellQuote(conf)} ${shellQuote(link)}`, SETUP_TIMEOUT_MS);
195	        }
196	        await reloadNginx(conn);
197	
198	        // PROVE it serves. "The job threw no exception" is not evidence, and
199	        // ACTIVE is load-bearing: lib/actions-websites.ts gates the SSL request
200	        // on it, so an unverified ACTIVE offers certbot HTTP-01 for a vhost that
201	        // may be answering 502 or not matching at all. A disabled site is not
202	        // linked into sites-enabled, so there is nothing to probe and we do not
203	        // pretend to have probed it.
204	        if (site.enabled) {
205	          // Deliberately NOT asserting the placeholder's content: the customer
206	          // may already have an index.php, and failing a working site because it
207	          // does not contain our filler text would be its own false report. What
208	          // is claimed is what is proved — this vhost answers for this Host
209	          // header, which is precisely the condition HTTP-01 needs. A 403/404
210	          // still proves nginx routed the request to this server block; a 502 or
211	          // a dead connection does not.
212	          proof = await verifyServing(conn, site.domain, [
213	            {
214	              path: "/",
215	              codes: ["200", "301", "302", "304", "403", "404"],
216	              require: [],
217	              reject: [/502 Bad Gateway/i, /504 Gateway Time-?out/i],
218	              proves: `nginx answers for ${site.domain}`,
219	            },
220	          ]);
221	        }
222	      });
223	    }
224	    await db.website.update({ where: { id: site.id }, data: { status: "ACTIVE", error: null } });
225	    await notify(
226	      site.userId,
227	      `Website ${site.domain} is live`,
228	      REAL
229	        ? site.enabled
230	          ? `Your nginx site is configured and serving — ${proof}.`
231	          : "Your nginx site is configured. It is currently disabled, so nothing is being served yet — enable it to go live."
232	        : "Simulated only (sandbox) — no VM was contacted and nothing is being served.",
233	      `/dashboard/servers/${site.serverId}?tab=control panel`
234	    );
235	  } catch (e: any) {
236	    const reason = String(e?.message ?? e).slice(0, 400);
237	    await db.website.update({ where: { id: site.id }, data: { status: "FAILED", error: reason } });
238	    await notify(site.userId, `Website ${site.domain} failed`, reason.slice(0, 200), `/dashboard/servers/${site.serverId}`);
239	  }
240	}
