242	/**
243	 * Link or unlink the vhost, reload, and — when enabling — PROVE it serves.
244	 *
245	 * The probe is not decoration here. `requestWebsiteSsl` in lib/actions-websites.ts
246	 * refuses unless `status === "ACTIVE"`, so ACTIVE is the gate that decides
247	 * whether certbot HTTP-01 is offered for this vhost. `websiteCreate` proves that
248	 * before writing ACTIVE (M7 #4); this path wrote the same ACTIVE having made no
249	 * request of any kind, which put the identical unverified value behind the same
250	 * gate — a customer who disabled and re-enabled a broken site got the HTTP-01
251	 * offer that M7 #4 was raised to prevent.
252	 */
253	export async function websiteToggle(job: Job): Promise<void> {
254	  const site = await loadSite(job);
255	  let proof = "";
256	  try {
257	    if (REAL) {
258	      assertDomain(site.domain);
259	      const server = await sshServer(site.serverId);
260	      const conf = `/etc/nginx/sites-available/${site.domain}.conf`;
261	      const link = `/etc/nginx/sites-enabled/${site.domain}.conf`;
262	      await withServerSsh(server, async (conn) => {
263	        if (site.enabled) await exec(conn, `ln -sf ${shellQuote(conf)} ${shellQuote(link)}`, SETUP_TIMEOUT_MS);
264	        else await exec(conn, `rm -f ${shellQuote(link)}`, SETUP_TIMEOUT_MS);
265	        await reloadNginx(conn);
266	        if (site.enabled) {
267	          // Same probe and same accepted codes as websiteCreate: a 403/404 still
268	          // proves nginx routed this Host to this server block, a 502 or a dead
269	          // connection does not.
270	          proof = await verifyServing(conn, site.domain, [
271	            {
272	              path: "/",
273	              codes: ["200", "301", "302", "304", "403", "404"],
274	              require: [],
275	              reject: [/502 Bad Gateway/i, /504 Gateway Time-?out/i],
276	              proves: `nginx answers for ${site.domain}`,
277	            },
278	          ]);
279	        }
280	      });
281	    }
282	    await db.website.update({ where: { id: site.id }, data: { status: site.enabled ? "ACTIVE" : "DISABLED", error: null } });
283	    await notify(
284	      site.userId,
285	      site.enabled ? `${site.domain} is enabled` : `${site.domain} is disabled`,
286	      site.enabled
287	        ? REAL
288	          ? `The vhost is linked and serving — ${proof}.`
289	          : "Enabled (sandbox) — no VM was contacted and nothing is being served."
290	        : "The vhost is unlinked, so this site is no longer served.",
291	      `/dashboard/servers/${site.serverId}?tab=control panel`
292	    );
293	  } catch (e: any) {
294	    const reason = String(e?.message ?? e).slice(0, 400);
295	    await db.website.update({ where: { id: site.id }, data: { status: "FAILED", error: reason } });
296	    // The row went FAILED in silence before, so a customer who enabled a site
297	    // and saw nothing happen had no way to learn why.
298	    await notify(
299	      site.userId,
300	      `Could not ${site.enabled ? "enable" : "disable"} ${site.domain}`,
301	      reason.slice(0, 200),
302	      `/dashboard/servers/${site.serverId}?tab=control panel`
303	    );
304	  }
305	}
306	
307	/**
308	 * Enable HTTPS on a customer site with `certbot --nginx`, and PROVE it.
309	 *
310	 * This handler used to accept
311	 *   run.code === 0 && /Congratulations|Successfully|not yet due for renewal|Deploying certificate/i
312	 * as its entire evidence, write `ssl: true`, and tell the customer "A Let's
313	 * Encrypt certificate is installed and HTTP redirects to HTTPS."
314	 *
315	 * That is the exact alternation M7 #6 took OUT of the certonly path and put
316	 * behind `classifyCertbotOutcome`: "not yet due for renewal" is what certbot
317	 * prints when it does nothing, and `/Successfully/i` matches most of its
318	 * chatter. Nothing was read back, so the sentence was sent unchanged when
319	 * certbot had just broken nginx (taking every OTHER site on the box down with
320	 * it), when nothing was listening on 443, and when http:// did not redirect
321	 * anywhere. `ssl: true` is also what the panel shows as a padlock.
322	 *
323	 * Now: the classifier decides whether certbot did anything, `probeTls` fetches
324	 * https://<domain> from inside the VM WITH certificate verification enabled
325	 * (no `-k` — a probe that disables verification cannot prove trust), checks the
326	 * redirect without following it, and reads nginx's state back. `websiteSslVerdict`
327	 * turns those observations into the one sentence the customer gets.
328	 */
329	export async function websiteSsl(job: Job): Promise<void> {
330	  const site = await loadSite(job);
331	  try {
332	    if (!REAL && !SANDBOX) {
333	      throw new Error(
334	        "Certificate issuance is switched off on this server (ENABLE_REAL_CPANEL is not set), so certbot " +
335	          "never ran and no certificate was installed for this site. HTTPS is NOT enabled. Ask support to " +
336	          "enable real control-panel provisioning."
337	      );
338	    }
339	
340	    let note = "SSL enabled (sandbox) — no VM was contacted and nothing is being served over HTTPS.";
341	    if (REAL) {
342	      assertDomain(site.domain);
343	      const server = await sshServer(site.serverId);
344	      const email = process.env.CERTBOT_EMAIL || "ssl-admin@nxeon.local";
345	      note = await withServerSsh(server, async (conn) => {
346	        const have = await exec(conn, "command -v certbot >/dev/null 2>&1 && echo yes || echo no", QUICK_TIMEOUT_MS);
347	        if (have.stdout.trim() !== "yes") {
348	          const prefix = await pkgInstallPrefix(conn);
349	          const inst = await exec(conn, `${prefix} certbot python3-certbot-nginx`, INSTALL_TIMEOUT_MS);
350	          if (inst.code !== 0) throw new Error(`certbot install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
351	        }
352	        // Use the nginx installer so the vhost is upgraded to 443 in place.
353	        const run = await exec(
354	          conn,
355	          `certbot --nginx -n --agree-tos -m ${shellQuote(email)} -d ${shellQuote(site.domain)} --redirect`,
356	          INSTALL_TIMEOUT_MS
357	        );
358	        const outcome = classifyCertbotOutcome(run.code, `${run.stdout}\n${run.stderr}`);
359	        // Read back what the site actually serves. An exit code is not proof,
360	        // and this is the step whose absence produced the false claim.
361	        const tls = await probeTls(conn, site.domain);
362	        const verdict = websiteSslVerdict(site.domain, {
363	          certbot: outcome.kind,
364	          httpsCode: tls.httpsCode,
365	          httpsRc: tls.httpsRc,
366	          httpCode: tls.httpCode,
367	          redirectTo: tls.redirectTo,
368	          nginxState: tls.nginxState,
369	          complete: tls.complete,
370	        });
371	        if (!verdict.ok) {
372	          throw new Error(
373	            outcome.kind === "failed" ? `${verdict.reason} certbot said: ${outcome.detail.slice(0, 200)}` : verdict.reason
374	          );
375	        }
376	        return verdict.note;
377	      });
378	    }
379	
380	    await db.website.update({ where: { id: site.id }, data: { ssl: true, error: null } });
381	    await notify(
382	      site.userId,
383	      `SSL enabled for ${site.domain}`,
384	      note.slice(0, 500),
385	      `/dashboard/servers/${site.serverId}?tab=control panel`
386	    );
387	  } catch (e: any) {
388	    const reason = String(e?.message ?? e).slice(0, 400);
389	    // `ssl` is NOT set to true on this path — the padlock in the panel must
390	    // never appear for a site whose HTTPS we could not verify.
391	    await db.website.update({ where: { id: site.id }, data: { error: reason } });
392	    await notify(site.userId, `SSL failed for ${site.domain}`, reason.slice(0, 200), `/dashboard/servers/${site.serverId}`);
393	  }
394	}
395	
396	export async function websiteDelete(job: Job): Promise<void> {
397	  const site = await loadSite(job);
398	  try {
399	    if (REAL) {
400	      assertDomain(site.domain);
401	      assertPath(site.docRoot);
402	      const server = await sshServer(site.serverId);
403	      const conf = `/etc/nginx/sites-available/${site.domain}.conf`;
404	      const link = `/etc/nginx/sites-enabled/${site.domain}.conf`;
405	      await withServerSsh(server, async (conn) => {
406	        await exec(conn, `rm -f ${shellQuote(link)} ${shellQuote(conf)}`, SETUP_TIMEOUT_MS);
407	        // Remove the docroot ONLY within /var/www (validated path); leave data
408	        // elsewhere untouched.
409	        if (site.docRoot.startsWith("/var/www/")) {
410	          await exec(conn, `rm -rf ${shellQuote(site.docRoot)}`, SETUP_TIMEOUT_MS);
411	        }
412	        // NOT `.catch(() => {})`. `reloadNginx` throws precisely when nginx is
413	        // not running afterwards, which means EVERY site on this VM is dark —
414	        // and swallowing it here then deleted the row, so the one signal that
415	        // the customer's whole server had just gone down was discarded and the
416	        // job reported success. The removals above are idempotent (`rm -f`,
417	        // `rm -rf` on a validated path), so failing and retrying is safe.
418	        await reloadNginx(conn);
419	      });
420	    }
421	    await db.website.delete({ where: { id: site.id } });
422	  } catch (e: any) {
423	    const reason = String(e?.message ?? e).slice(0, 400);
424	    // The row may already be gone (a failure after the delete); never let the
425	    // bookkeeping throw over the top of the real error.
426	    await db.website
427	      .update({ where: { id: site.id }, data: { status: "FAILED", error: reason } })
428	      .catch(() => {});
429	    await notify(
430	      site.userId,
431	      `Could not finish removing ${site.domain}`,
432	      reason.slice(0, 200),
433	      `/dashboard/servers/${site.serverId}?tab=control panel`
434	    );
435	    throw new Error(`website delete not verified: ${reason}`);
436	  }
437	}
