255	// ----------------------------------------------------------------------------
256	// Typed operations (sandbox-aware)
257	// ----------------------------------------------------------------------------
258	
259	export async function listDir(server: SftpServer, path: string): Promise<SftpEntry[]> {
260	  if (SANDBOX) {
261	    const node = simResolve(server.id, path);
262	    if (!node) throw new Error("No such directory.");
263	    if (node.type !== "dir") throw new Error("Not a directory.");
264	    return Object.entries(node.children)
265	      .map(([name, child]) => ({
266	        name,
267	        type: child.type === "dir" ? "d" : "-",
268	        isDirectory: child.type === "dir",
269	        size: child.type === "file" ? Buffer.byteLength(child.content) : 0,
270	        modifiedMs: child.mtime,
271	        mode: child.mode,
272	      }))
273	      .sort((a, b) =>
274	        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
275	      );
276	  }
277	
278	  return withSftp(server, async (client) => {
279	    const list = await client.list(path);
280	    return list
281	      .map((e) => ({
282	        name: e.name,
283	        type: e.type,
284	        isDirectory: e.type === "d",
285	        size: e.size,
286	        modifiedMs: e.modifyTime,
287	        // ssh2-sftp-client's list() returns rwx `rights` strings, not a numeric
288	        // mode — derive the octal permission bits from them.
289	        mode: rightsToMode(e.rights),
290	      }))
291	      .sort((a, b) =>
292	        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
293	      );
294	  });
295	}
296	
297	export async function statPath(server: SftpServer, path: string): Promise<SftpStat> {
298	  if (SANDBOX) {
299	    const node = simResolve(server.id, path);
300	    if (!node) throw new Error("No such file or directory.");
301	    return {
302	      isDirectory: node.type === "dir",
303	      size: node.type === "file" ? Buffer.byteLength(node.content) : 0,
304	      modifiedMs: node.mtime,
305	      mode: node.mode,
306	    };
307	  }
308	
309	  return withSftp(server, async (client) => {
310	    const s = await client.stat(path);
311	    return {
312	      isDirectory: s.isDirectory,
313	      size: s.size,
314	      modifiedMs: s.modifyTime,
315	      mode: typeof s.mode === "number" ? s.mode & 0o777 : null,
316	    };
317	  });
318	}
