258	/**
259	 * A generated secret is about to be embedded in a SQL/PHP string literal or a
260	 * credentials file (delivered over STDIN). `generateStrongPassword` is
261	 * alphanumeric by design; assert it, because a stray quote, colon or backslash
262	 * would break out of that literal — `.pgpass` and MySQL defaults files are both
263	 * colon/backslash sensitive.
264	 *
265	 * Lifted out of worker/apps.ts so worker/databases.ts can reuse it rather than
266	 * grow a second copy that drifts.
267	 */
268	export function assertInertSecret(secret: string, what: string): void {
269	  assert(/^[A-Za-z0-9]{8,128}$/.test(secret), `Unexpected ${what} shape — refusing to use it.`);
270	}
