277	/** A URL-safe generated password (no shell metacharacters, no ambiguity). */
278	export function generateStrongPassword(len = 20): string {
279	  return randomBytes(len * 2)
280	    .toString("base64url")
281	    .replace(/[-_]/g, "")
282	    .slice(0, len);
283	}
