export async function verifyServing(conn: Client, domain: string, probes: Probe[]): Promise<string> {
  const proof: string[] = [];
  for (const p of probes) {
    const { code, body } = await httpProbe(conn, domain, p.path);
    if (!(p.codes ?? ["200"]).includes(code))
      throw new Error(`verification failed: ${p.path} returned HTTP ${code}, so ${p.proves} is not true.`);
    for (const re of p.reject ?? []) {
      const hit = re.exec(body);
      if (hit) throw new Error(`verification failed: ${p.path} returned an application error ("${hit[0].slice(0, 80)}").`);
    }
    for (const re of p.require) {
      if (!re.test(body))
        throw new Error(`verification failed: ${p.path} answered 200 but ${p.proves} could not be confirmed.`);
    }
    proof.push(`${p.path}=${code}`);
  }
  return `verified from the VM (${proof.join(" ")})`;
}

