/**
 * Website Builder — PURE rendering + validation (no IO, fully testable).
 *
 * Turns an editor document (GrapesJS HTML + CSS per page) into the final static
 * files that get written into `/var/www/<domain>` by worker/site-publish.ts.
 * Nothing here touches the network, the DB, or the filesystem — that is what
 * makes it safe to unit-test and to reason about the published output.
 *
 * The published output is deliberately static: each page becomes one complete,
 * self-contained HTML document with its CSS inlined in a <style> tag. No runtime,
 * no external requests, no per-site process — it drops straight onto the nginx
 * static hosting Nxeon already runs.
 */

/** One page of a site, as produced by the GrapesJS editor. */
export type SitePageDoc = {
  /** Route path: "/", "/about", "/contact". Always starts with "/". */
  path: string;
  title?: string;
  seoDesc?: string;
  /** Body markup — GrapesJS `editor.getHtml()`. */
  html: string;
  /** Stylesheet — GrapesJS `editor.getCss()`. */
  css: string;
  /**
   * Opaque GrapesJS `editor.getProjectData()` used ONLY to reload the draft into
   * the editor. Never rendered into the published output.
   */
  projectData?: unknown;
};

/** The whole editable document for a site — one blob stored as SiteVersion.document. */
export type SiteDocument = {
  pages: SitePageDoc[];
};

/** A file to write into the doc root, path relative to the doc root. */
export type RenderedFile = { file: string; contents: string };

/** Options that affect the rendered <head> but not the body. */
export type RenderOptions = {
  /** Site name — used as a fallback <title> when a page has none. */
  siteName?: string;
};

// ---------------------------------------------------------------------------
// Slugs (→ *.nxeon subdomain label)
// ---------------------------------------------------------------------------

/** A valid DNS label: lowercase alphanumerics + internal hyphens, 1..63 chars. */
export const SLUG_RE = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/;

export function isValidSlug(s: unknown): s is string {
  return typeof s === "string" && SLUG_RE.test(s);
}

/**
 * Coerce arbitrary text into a safe subdomain label: lowercase, collapse every
 * run of non `[a-z0-9]` into a single hyphen, strip leading/trailing hyphens,
 * cap at 63 chars. Returns "" when nothing usable survives — callers MUST treat
 * an empty result as "generate a fallback", never publish it.
 */
export function sanitizeSlug(input: unknown): string {
  return String(input ?? "")
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 63)
    .replace(/-+$/g, ""); // a trailing hyphen can reappear after the 63-char cut
}

// ---------------------------------------------------------------------------
// HTML helpers
// ---------------------------------------------------------------------------

/** Escape the five HTML-significant characters for use in text / attributes. */
export function escapeHtml(s: unknown): string {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/**
 * Map a route path to the static file that serves it, so nginx's `try_files`
 * resolves clean URLs: "/" → "index.html", "/about" → "about/index.html".
 * Each segment is sanitized to `[a-z0-9-]`; an empty/degenerate path renders as
 * the site index.
 */
export function pageFilePath(routePath: string): string {
  const segments = String(routePath ?? "")
    .split("/")
    .map((seg) => sanitizeSlug(seg))
    .filter((seg) => seg.length > 0);
  if (segments.length === 0) return "index.html";
  return `${segments.join("/")}/index.html`;
}

// ---------------------------------------------------------------------------
// Rendering
// ---------------------------------------------------------------------------

/** A minimal reset so templates behave the same across browsers. */
const BASE_RESET = "*,*::before,*::after{box-sizing:border-box}body{margin:0}img{max-width:100%;height:auto}";

/** Render ONE page into a complete, self-contained HTML document. */
export function renderPage(page: SitePageDoc, opts: RenderOptions = {}): string {
  const title = escapeHtml(page.title || opts.siteName || "My site");
  const descMeta = page.seoDesc
    ? `\n    <meta name="description" content="${escapeHtml(page.seoDesc)}">`
    : "";
  const css = typeof page.css === "string" ? page.css : "";
  const body = typeof page.html === "string" ? page.html : "";
  return `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>${title}</title>${descMeta}
    <meta name="generator" content="Nxeon Website Builder">
    <style>
${BASE_RESET}
${css}
    </style>
  </head>
  <body>
${body}
  </body>
</html>
`;
}

/**
 * Render a whole site document to the set of static files to publish. Throws on
 * an empty/invalid document — a publish that would write nothing must FAIL loudly
 * rather than swap an empty directory over a live site.
 */
export function renderSite(doc: SiteDocument, opts: RenderOptions = {}): RenderedFile[] {
  if (!isSiteDocument(doc) || doc.pages.length === 0) {
    throw new Error("Nothing to publish — the site has no pages.");
  }
  const seen = new Set<string>();
  const files: RenderedFile[] = [];
  let hasIndex = false;
  for (const page of doc.pages) {
    const file = pageFilePath(page.path);
    if (seen.has(file)) {
      throw new Error(`Two pages resolve to the same file (${file}) — page paths must be unique.`);
    }
    seen.add(file);
    if (file === "index.html") hasIndex = true;
    files.push({ file, contents: renderPage(page, opts) });
  }
  if (!hasIndex) {
    throw new Error('A site must have a home page (path "/").');
  }
  return files;
}

// ---------------------------------------------------------------------------
// Validation (used by the save-draft action before persisting client input)
// ---------------------------------------------------------------------------

function isPageDoc(x: unknown): x is SitePageDoc {
  if (typeof x !== "object" || x === null) return false;
  const p = x as Record<string, unknown>;
  return (
    typeof p.path === "string" &&
    p.path.startsWith("/") &&
    typeof p.html === "string" &&
    typeof p.css === "string" &&
    (p.title === undefined || typeof p.title === "string") &&
    (p.seoDesc === undefined || typeof p.seoDesc === "string")
  );
}

/** Type guard for a document coming off the wire (client save) or the DB. */
export function isSiteDocument(x: unknown): x is SiteDocument {
  if (typeof x !== "object" || x === null) return false;
  const d = x as Record<string, unknown>;
  return Array.isArray(d.pages) && d.pages.every(isPageDoc);
}

/**
 * Website Builder — starter templates.
 *
 * Each template is a small, responsive, single-page starting point: the initial
 * GrapesJS document (HTML + CSS for the home page) plus display metadata for the
 * template picker. `createSite` copies the chosen template's `document` into the
 * new site's first draft SiteVersion, and the editor loads it from there.
 *
 * These are intentionally plain HTML/CSS (no projectData): GrapesJS imports raw
 * HTML+CSS happily via `editor.setComponents()` / `editor.setStyle()`, so a fresh
 * template needs no editor-specific project blob — the customer's edits generate
 * one on first save. Everything here is static and self-contained.
 */
import type { SiteDocument } from "./site-render";

export type SiteTemplate = {
