  accent: string;
  document: SiteDocument;
};

/** Shared page shell helper keeps the templates below compact and consistent. */
function page(html: string, css: string, title: string, seoDesc: string): SiteDocument {
  return { pages: [{ path: "/", title, seoDesc, html, css }] };
}

