import type { Job } from "@prisma/client";

/**
 * Website Builder — SITE_PUBLISH / SITE_UNPUBLISH handlers.
 *
 * Registered in worker/index.ts:
 *   SITE_PUBLISH:   sitePublish,
 *   SITE_UNPUBLISH: siteUnpublish,
 *
 * Modelled on worker/websites.ts. A Site's draft document is rendered to a static
 * HTML/CSS bundle (lib/site-render.ts — pure) and written into
 * `/var/www/<slug>.<base>` on a shared builder host, reusing the same nginx vhost
 * + `nginx -t` gate + serve-probe machinery the control panel already runs. The
 * Site publishes INTO a Website row (created here, bound to the builder server) so
 * the existing SSL sweep can pick up the subdomain unchanged.
 *
 * HONESTY. A Site is set PUBLISHED only when the bundle was really written, nginx
 * reloaded green, and the vhost answered — mirroring websiteCreate. On any failure
 * the Site goes FAILED with the reason; success is never faked.
 *
 * GATING (identical shape to worker/websites.ts):
 *   - SANDBOX (staging): no SSH. The publish is SIMULATED — the Site flips to
 *     PUBLISHED so the whole builder UX works end to end, but nothing real is
 *     touched and the notification says so.
 *   - prod with ENABLE_REAL_PUBLISH=1: the real render/write/reload runs.
 *   - prod with the flag OFF: we THROW rather than fake success, so a fresh prod
 *     box can't report a live site having touched nothing.
 */
const REAL = !SANDBOX && process.env.ENABLE_REAL_PUBLISH === "1";

/** Base domain for the shared builder host: sites publish to `<slug>.<base>`. */
const BASE_DOMAIN = process.env.SITE_BUILDER_BASE_DOMAIN || "nxeon.site";
/** The Server row (id) that hosts the shared builder vhosts. Required for REAL. */
const BUILDER_SERVER_ID = process.env.SITE_BUILDER_SERVER_ID || "";

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[site-publish] notify failed", e);
  }
}

async function loadSite(job: Job) {
  const p = (job.payload ?? {}) as { siteId?: string };
  if (!p.siteId) throw new Error("site job: missing siteId");
  const site = await db.site.findUnique({ where: { id: p.siteId } });
  if (!site) throw new Error(`Site ${p.siteId} not found`);
  return site;
}

function publishDomain(slug: string): string {
  return `${slug}.${BASE_DOMAIN}`;
}

/** Load the latest draft document for a site, or throw if there is nothing to publish. */
async function loadDraftDocument(siteId: string): Promise<SiteDocument> {
  const draft = await db.siteVersion.findFirst({
    where: { siteId, isDraft: true },
    orderBy: { createdAt: "desc" },
  });
  if (!draft) throw new Error("There is no saved draft to publish.");
  return draft.document as unknown as SiteDocument;
}

/**
 * Ensure a Website row exists for this Site's builder subdomain, so the nginx/SSL
 * binding is the same Website the control panel manages. Reuses the site's stored
 * websiteId if present, otherwise creates one bound to the builder server. Returns
 * the Website row.
 */
async function ensureBuilderWebsite(site: {
  id: string;
  userId: string;
  slug: string;
  websiteId: string | null;
}, domain: string, docRoot: string) {
  if (site.websiteId) {
    const existing = await db.website.findUnique({ where: { id: site.websiteId } });
    if (existing) return existing;
  }
  // Reuse a row for this exact (builder server, domain) if one is already there
  // (the @@unique([serverId, domain]) makes a blind create unsafe on retry).
  const found = await db.website.findFirst({ where: { serverId: BUILDER_SERVER_ID, domain } });
  if (found) return found;
  return db.website.create({
    data: {
      userId: site.userId,
      serverId: BUILDER_SERVER_ID,
      domain,
      docRoot,
      phpVersion: null, // static site — no PHP-FPM
      enabled: true,
      status: "PENDING",
    },
  });
}

/** Fail if a remote command did not exit 0 — the same rigour websites.ts applies. */
function assertOk(r: { code: number | null; stdout: string; stderr: string }, what: string): void {
  if (r.code !== 0) {
    throw new Error(`${what} failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
  }
}

// ---------------------------------------------------------------------------

export async function sitePublish(job: Job): Promise<void> {
  const site = await loadSite(job);
  try {
    // Render FIRST (pure, no IO). This validates the document and guarantees we
    // never swap an empty directory over a live site — renderSite throws on an
    // empty/invalid document or a missing home page.
    const document = await loadDraftDocument(site.id);
    const files = renderSite(document, { siteName: site.name });

    const domain = publishDomain(site.slug);
    assertDomain(domain);
    const docRoot = `/var/www/${domain}`;
    assertPath(docRoot);

    // Simulation is a SANDBOX-only affordance and MUST NEVER run in production.
    // Same guard as websiteCreate: without it a prod box that lost the flag would
    // write PUBLISHED and tell the customer their site is live having touched
    // nothing.
    if (!REAL && !SANDBOX) {
      throw new Error(
        "Publishing is switched off on this server (ENABLE_REAL_PUBLISH is not set), so no files were " +
          "written and no vhost was created. Your site is NOT live. Ask support to enable real publishing."
      );
    }

    let proof = "simulated (sandbox) — no VM was contacted and nothing is being served";
    let websiteId: string | null = site.websiteId;

    if (REAL) {
      if (!BUILDER_SERVER_ID) {
        throw new Error(
          "No builder host is configured (SITE_BUILDER_SERVER_ID is unset), so there is nowhere to publish to."
        );
      }
      const website = await ensureBuilderWebsite(site, domain, docRoot);
      websiteId = website.id;
      const server = await sshServer(BUILDER_SERVER_ID);

      const conf = `/etc/nginx/sites-available/${domain}.conf`;
      const link = `/etc/nginx/sites-enabled/${domain}.conf`;
      // A per-job release directory we build in full, then swap in atomically. Its
      // charset is allowlist-clean (domain + job.id are [a-z0-9.-]); assert anyway.
      const release = `${docRoot}.rel-${job.id}`;
      assertPath(release);

      proof = await withServerSsh(server, async (conn) => {
        await ensureNginx(conn);

        // 1. Vhost first, so nginx already routes this Host to `docRoot` before we
        //    put content there. Written via STDIN, never as an argv token.
        await execInput(conn, `cat > ${shellQuote(conf)}`, nginxVhost(domain, docRoot, null), SETUP_TIMEOUT_MS);
        assertOk(
          await exec(conn, `ln -sf ${shellQuote(conf)} ${shellQuote(link)}`, SETUP_TIMEOUT_MS),
          "enable vhost"
        );

        // 2. Build the FULL bundle in the release dir. Nothing touches the live
        //    docRoot yet, so a failure here leaves the running site untouched.
        assertOk(await exec(conn, `rm -rf ${shellQuote(release)}`, SETUP_TIMEOUT_MS), "clear stale release");
        assertOk(await exec(conn, `mkdir -p ${shellQuote(release)}`, SETUP_TIMEOUT_MS), "create release dir");
        for (const f of files) {
          const dest = `${release}/${f.file}`;
          const dir = dest.slice(0, dest.lastIndexOf("/"));
          assertOk(await exec(conn, `mkdir -p ${shellQuote(dir)}`, SETUP_TIMEOUT_MS), "create page dir");
          assertOk(
            await execInput(conn, `cat > ${shellQuote(dest)}`, f.contents, SETUP_TIMEOUT_MS),
            "write page"
          );
        }
        assertOk(
          await exec(conn, `chown -R www-data:www-data ${shellQuote(release)} 2>/dev/null || true`, SETUP_TIMEOUT_MS),
          "set ownership"
        );

        // 3. Atomic swap: move the old docRoot aside, move the release into place,
        //    then discard the old copy. `mv` on the same filesystem is a rename —
        //    the window in which docRoot doesn't exist is sub-millisecond, and the
        //    two moves are exit-code checked so a half-swap becomes a job failure,
        //    not a broken live site.
        const trash = `${docRoot}.old`;
        await exec(conn, `rm -rf ${shellQuote(trash)}`, SETUP_TIMEOUT_MS);
        await exec(conn, `test -e ${shellQuote(docRoot)} && mv ${shellQuote(docRoot)} ${shellQuote(trash)} || true`, SETUP_TIMEOUT_MS);
        assertOk(await exec(conn, `mv ${shellQuote(release)} ${shellQuote(docRoot)}`, SETUP_TIMEOUT_MS), "swap release into place");
        await exec(conn, `rm -rf ${shellQuote(trash)}`, SETUP_TIMEOUT_MS);

        // 4. Reload behind the `nginx -t` gate, and confirm nginx is actually
        //    running afterwards (reloadNginx throws otherwise).
        await reloadNginx(conn);

        // 5. PROVE it serves. As in websiteCreate, a 200/301/302/304/403/404 shows
        //    nginx routed this Host to this server block; a 502/504 or dead
        //    connection does not, and must fail the publish.
        return verifyServing(conn, domain, [
          {
            path: "/",
            codes: ["200", "301", "302", "304", "403", "404"],
            require: [],
            reject: [/502 Bad Gateway/i, /504 Gateway Time-?out/i],
            proves: `the published site answers for ${domain}`,
          },
        ]);
      });

      await db.website.update({ where: { id: website.id }, data: { status: "ACTIVE", error: null } });
    }

    // Record an immutable published snapshot (draft + rollback for free) and flip
    // the Site to PUBLISHED — only now, after the work above really succeeded.
    await db.siteVersion.create({
      data: {
        siteId: site.id,
        document: document as unknown as object,
        isDraft: false,
        label: "Published",
        publishedAt: new Date(),
      },
    });
    await db.site.update({
      where: { id: site.id },
      data: { status: "PUBLISHED", publishedAt: new Date(), error: null, websiteId },
    });

    const url = `http://${domain}/`;
    await notify(
      site.userId,
      `${site.name} is live`,
      REAL
        ? `Your site is published and serving at ${url} — ${proof}.`
        : `Simulated only (sandbox) — no VM was contacted. Nothing is being served at ${url}.`,
      "/dashboard/sites"
    );
  } catch (e: any) {
    const reason = String(e?.message ?? e).slice(0, 400);
    await db.site.update({ where: { id: site.id }, data: { status: "FAILED", error: reason } });
    await notify(site.userId, `Publishing ${site.name} failed`, reason.slice(0, 200), "/dashboard/sites");
  }
}

export async function siteUnpublish(job: Job): Promise<void> {
  const site = await loadSite(job);
  try {
    if (!REAL && !SANDBOX) {
      throw new Error(
        "Publishing is switched off on this server (ENABLE_REAL_PUBLISH is not set); nothing was changed."
      );
    }

    if (REAL && site.websiteId) {
      const website = await db.website.findUnique({ where: { id: site.websiteId } });
      if (website) {
        assertDomain(website.domain);
        assertPath(website.docRoot);
        const server = await sshServer(website.serverId);
        const conf = `/etc/nginx/sites-available/${website.domain}.conf`;
        const link = `/etc/nginx/sites-enabled/${website.domain}.conf`;
        await withServerSsh(server, async (conn) => {
          await exec(conn, `rm -f ${shellQuote(link)} ${shellQuote(conf)}`, SETUP_TIMEOUT_MS);
          // Only remove the docRoot within /var/www (validated) — never elsewhere.
          if (website.docRoot.startsWith("/var/www/")) {
            await exec(conn, `rm -rf ${shellQuote(website.docRoot)}`, SETUP_TIMEOUT_MS);
          }
          // reloadNginx throws precisely when nginx is dead afterwards — which
          // would mean every OTHER site on the builder host is down too, so the
          // signal must not be swallowed.
          await reloadNginx(conn);
        });
        await db.website.delete({ where: { id: website.id } }).catch(() => {});
      }
    }

    await db.site.update({
      where: { id: site.id },
      data: { status: "DRAFT", publishedAt: null, websiteId: null, error: null },
    });
    await notify(
      site.userId,
      `${site.name} was taken offline`,
      REAL
        ? "The site is no longer served and its files were removed from the builder host."
        : "Unpublished (sandbox) — no VM was contacted.",
      "/dashboard/sites"
    );
  } catch (e: any) {
    const reason = String(e?.message ?? e).slice(0, 400);
    await db.site.update({ where: { id: site.id }, data: { status: "FAILED", error: reason } });
    await notify(site.userId, `Could not take ${site.name} offline`, reason.slice(0, 200), "/dashboard/sites");
  }
}

