"use client";

/**
 * Customer-facing site list + create/publish controls for the Website Builder.
 *
 * All mutations go through the `"use server"` actions in lib/actions-sites.ts,
 * which authenticate and ownership-check every call — this component only drives
 * the UI and surfaces the result.
 */
import { useState, useTransition } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  createSite,
  publishSite,
  unpublishSite,
  deleteSite,
} from "@/lib/actions-sites";
import type { SiteRow } from "@/lib/actions-sites";
import { PageHeader, EmptyState, StatusDot, Badge } from "@/components/ui/primitives";

export type TemplateChoice = {
  key: string;
  name: string;
  description: string;
  accent: string;
};

export function SitesManager({
  sites,
  templates,
  baseDomain,
}: {
  sites: SiteRow[];
  templates: TemplateChoice[];
  baseDomain: string;
}) {
  const router = useRouter();
  const [name, setName] = useState("");
  const [templateKey, setTemplateKey] = useState(templates[0]?.key ?? "");
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  function onCreate() {
    setError(null);
    start(async () => {
      const res = await createSite(name.trim() || "My site", templateKey);
      if (!res.ok) {
        setError(res.error);
        return;
      }
      router.push(`/dashboard/sites/${res.id}`);
    });
  }

  function onPublish(id: string) {
    setError(null);
    start(async () => {
      const res = await publishSite(id);
      if (!res.ok) setError(res.error);
      router.refresh();
    });
  }

  function onUnpublish(id: string) {
    setError(null);
    start(async () => {
      const res = await unpublishSite(id);
      if (!res.ok) setError(res.error);
      router.refresh();
    });
  }

  function onDelete(id: string) {
    setError(null);
    if (!confirm("Delete this site permanently? This cannot be undone.")) return;
    start(async () => {
      const res = await deleteSite(id);
      if (!res.ok) setError(res.error);
      router.refresh();
    });
  }

  return (
    <div>
      <PageHeader
        title="Website builder"
        sub="Pick a template, edit it in your browser, and publish a live site in one click."
      />

      {error && (
        <div className="card mb-4 border-red-500/40 bg-red-500/10 p-3 text-sm text-red-300">{error}</div>
      )}

      {/* Create a new site */}
      <div className="card mb-8 p-5">
        <h2 className="mb-4 text-sm font-semibold text-slate-200">Create a new site</h2>
        <div className="mb-4 grid gap-3 sm:grid-cols-3">
          {templates.map((t) => (
            <button
              key={t.key}
              type="button"
              onClick={() => setTemplateKey(t.key)}
              className={`rounded-xl border p-4 text-left transition ${
                templateKey === t.key
                  ? "border-brand-500 bg-brand-500/10"
                  : "border-white/10 bg-white/[0.03] hover:border-white/20"
              }`}
            >
              <div className="mb-2 h-2 w-10 rounded-full" style={{ background: t.accent }} />
              <div className="text-sm font-semibold">{t.name}</div>
              <div className="mt-1 text-xs text-slate-400">{t.description}</div>
            </button>
          ))}
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <input
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="Site name (e.g. My Cafe)"
            maxLength={80}
            className="min-w-[220px] flex-1 rounded-lg border border-white/10 bg-navy-950/60 px-3 py-2 text-sm outline-none focus:border-brand-500"
          />
          <button
            type="button"
            onClick={onCreate}
            disabled={pending}
            className="rounded-lg bg-brand-500 px-5 py-2 text-sm font-semibold text-white disabled:opacity-50"
          >
            {pending ? "Working…" : "Create site"}
          </button>
        </div>
      </div>

      {/* Existing sites */}
      {sites.length === 0 ? (
        <EmptyState
          title="No sites yet"
          sub="Choose a template above to start building your first website."
        />
      ) : (
        <div className="space-y-3">
          {sites.map((s) => {
            const domain = `${s.slug}.${baseDomain}`;
            const live = s.status === "PUBLISHED";
            const busy = s.status === "PUBLISHING";
            return (
              <div key={s.id} className="card flex flex-wrap items-center justify-between gap-4 p-4">
                <div className="min-w-0">
                  <div className="flex items-center gap-2">
                    <span className="truncate font-semibold">{s.name}</span>
                    <StatusDot status={s.status} />
                  </div>
                  <div className="mt-1 text-xs text-slate-400">
                    {live ? (
                      <a
                        href={`http://${domain}/`}
                        target="_blank"
                        rel="noreferrer"
                        className="text-brand-300 hover:underline"
                      >
                        {domain}
                      </a>
                    ) : (
                      <span>{domain}</span>
                    )}
                    {s.templateKey && (
                      <>
                        {" · "}
                        <Badge tone="slate">{s.templateKey}</Badge>
                      </>
                    )}
                  </div>
                  {s.status === "FAILED" && s.error && (
                    <div className="mt-1 max-w-xl text-xs text-red-300">{s.error}</div>
                  )}
                </div>
                <div className="flex flex-wrap items-center gap-2">
                  <Link
                    href={`/dashboard/sites/${s.id}`}
                    className="rounded-lg border border-white/10 px-3 py-1.5 text-sm hover:border-white/25"
                  >
                    Edit
                  </Link>
                  {live || s.status === "FAILED" ? (
                    <button
                      type="button"
                      onClick={() => onUnpublish(s.id)}
                      disabled={pending || busy}
                      className="rounded-lg border border-white/10 px-3 py-1.5 text-sm hover:border-white/25 disabled:opacity-50"
                    >
                      Take offline
                    </button>
                  ) : (
                    <button
                      type="button"
                      onClick={() => onPublish(s.id)}
                      disabled={pending || busy}
                      className="rounded-lg bg-brand-500 px-3 py-1.5 text-sm font-semibold text-white disabled:opacity-50"
                    >
                      {busy ? "Publishing…" : "Publish"}
                    </button>
                  )}
                  <button
                    type="button"
                    onClick={() => onDelete(s.id)}
                    disabled={pending || live || busy}
                    className="rounded-lg border border-white/10 px-3 py-1.5 text-sm text-red-300 hover:border-red-500/40 disabled:opacity-40"
                  >
                    Delete
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

"use client";

/**
 * GrapesJS editor wrapper for the Website Builder.
 *
 * GrapesJS touches `window`/DOM, so it is imported dynamically INSIDE a useEffect
 * (never at module top level) and only ever runs in the browser. The published
 * output is the editor's static export — `editor.getHtml()` + `editor.getCss()` —
 * and the reloadable draft is `editor.getProjectData()`, both persisted through
 * the ownership-checked `saveDraft` server action as a SiteDocument.
 *
 * The MVP editor edits the site's home page ("/"). Other pages a template ships
 * with are preserved untouched in the saved document.
 */
import "grapesjs/dist/css/grapes.min.css";
import { useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import type { Editor } from "grapesjs";
import { saveDraft, publishSite, type SiteRow } from "@/lib/actions-sites";
import type { SiteDocument, SitePageDoc } from "@/lib/site-render";

export function SiteEditor({
  site,
  document: initialDoc,
  baseDomain,
}: {
  site: SiteRow;
  document: SiteDocument | null;
  baseDomain: string;
}) {
  const router = useRouter();
  const holderRef = useRef<HTMLDivElement | null>(null);
  const editorRef = useRef<Editor | null>(null);
  // Pages OTHER than "/" are kept verbatim and re-merged on save.
  const otherPagesRef = useRef<SitePageDoc[]>([]);
  const [ready, setReady] = useState(false);
  const [status, setStatus] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    let editor: Editor | null = null;
    let cancelled = false;

    (async () => {
      const grapesjs = (await import("grapesjs")).default;
      const preset = (await import("grapesjs-preset-webpage")).default;
      if (cancelled || !holderRef.current) return;

      const pages = initialDoc?.pages ?? [];
      const home = pages.find((p) => p.path === "/") ?? pages[0];
      otherPagesRef.current = pages.filter((p) => p !== home);

      editor = grapesjs.init({
        container: holderRef.current,
        height: "100%",
        fromElement: false,
        storageManager: false, // we persist via the saveDraft server action
        // GrapesJS ships a device manager (desktop / tablet / mobile) — the
        // responsive breakpoint switcher the MVP requires.
        deviceManager: {
          devices: [
            { name: "Desktop", width: "" },
            { name: "Tablet", width: "768px", widthMedia: "992px" },
            { name: "Mobile", width: "375px", widthMedia: "575px" },
          ],
        },
        plugins: [preset as unknown as (e: Editor) => void],
        pluginsOpts: {},
      });

      // Load the existing draft: prefer the reloadable project blob, else import
      // the raw template HTML+CSS.
      const projectData = (home as SitePageDoc | undefined)?.projectData;
      if (projectData && typeof projectData === "object") {
        editor.loadProjectData(projectData as Record<string, unknown>);
      } else if (home) {
        editor.setComponents(home.html || "");
        editor.setStyle(home.css || "");
      }

      editorRef.current = editor;
      if (!cancelled) setReady(true);
    })();

    return () => {
      cancelled = true;
      try {
        editor?.destroy();
      } catch {
        /* best effort */
      }
      editorRef.current = null;
    };
    // Initialise once for this site; initialDoc is a snapshot at mount time.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function currentDocument(): SiteDocument {
    const editor = editorRef.current;
    const home = initialDoc?.pages.find((p) => p.path === "/");
    const homePage: SitePageDoc = {
      path: "/",
      title: home?.title,
      seoDesc: home?.seoDesc,
      html: editor ? editor.getHtml() : home?.html ?? "",
      css: editor ? editor.getCss({}) ?? "" : home?.css ?? "",
      projectData: editor ? editor.getProjectData() : home?.projectData,
    };
    return { pages: [homePage, ...otherPagesRef.current] };
  }

  async function doSave(): Promise<boolean> {
    const res = await saveDraft(site.id, currentDocument());
    if (!res.ok) {
      setStatus(res.error);
      return false;
    }
    setStatus("Draft saved.");
    return true;
  }

  function onSave() {
    setBusy(true);
    setStatus(null);
    doSave().finally(() => setBusy(false));
  }

  function onPublish() {
    setBusy(true);
    setStatus(null);
    (async () => {
      const saved = await doSave();
      if (!saved) return;
      const res = await publishSite(site.id);
      if (!res.ok) {
        setStatus(res.error);
        return;
      }
      setStatus("Publishing… this can take a moment.");
      router.push("/dashboard/sites");
    })().finally(() => setBusy(false));
  }

  const domain = `${site.slug}.${baseDomain}`;

  return (
    <div className="flex h-[calc(100vh-4rem)] flex-col">
      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-white/10 px-4 py-3">
        <div className="min-w-0">
          <div className="truncate text-sm font-semibold">{site.name}</div>
          <div className="text-xs text-slate-400">{domain}</div>
        </div>
        <div className="flex items-center gap-2">
          {status && <span className="text-xs text-slate-400">{status}</span>}
          <button
            type="button"
            onClick={() => router.push("/dashboard/sites")}
            className="rounded-lg border border-white/10 px-3 py-1.5 text-sm hover:border-white/25"
          >
            Back
          </button>
          <button
            type="button"
            onClick={onSave}
            disabled={!ready || busy}
            className="rounded-lg border border-white/10 px-3 py-1.5 text-sm hover:border-white/25 disabled:opacity-50"
          >
            Save draft
          </button>
          <button
            type="button"
            onClick={onPublish}
            disabled={!ready || busy}
            className="rounded-lg bg-brand-500 px-4 py-1.5 text-sm font-semibold text-white disabled:opacity-50"
          >
            Publish
          </button>
        </div>
      </div>
      <div className="relative flex-1 overflow-hidden">
        {!ready && (
          <div className="absolute inset-0 flex items-center justify-center text-sm text-slate-400">
            Loading editor…
          </div>
        )}
        <div ref={holderRef} className="h-full" />
      </div>
    </div>
  );
}

import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { AutoRefresh } from "@/components/AutoRefresh";
import { SitesManager, type TemplateChoice } from "@/components/customer/site-builder/SitesManager";
import type { SiteRow } from "@/lib/actions-sites";
import { SITE_TEMPLATES } from "@/lib/site-templates";

export const dynamic = "force-dynamic";

const BASE_DOMAIN = process.env.SITE_BUILDER_BASE_DOMAIN || "nxeon.site";

export default async function SitesPage() {
  const user = await requireUser();

  const sites = await db.site.findMany({
    where: { userId: user.id },
    orderBy: { updatedAt: "desc" },
  });

  const rows: SiteRow[] = sites.map((s) => ({
    id: s.id,
    name: s.name,
    slug: s.slug,
    status: s.status,
    templateKey: s.templateKey,
    publishedAt: s.publishedAt ? s.publishedAt.toISOString() : null,
    error: s.error,
    updatedAt: s.updatedAt.toISOString(),
  }));

  const templates: TemplateChoice[] = SITE_TEMPLATES.map((t) => ({
    key: t.key,
    name: t.name,
    description: t.description,
    accent: t.accent,
  }));

  // Refresh while any site is mid-publish so the status flips without a manual
  // reload (the worker is serial, so a publish can briefly queue).
  const anyBusy = rows.some((r) => r.status === "PUBLISHING");

  return (
    <>
      {anyBusy && <AutoRefresh intervalMs={5000} />}
      <SitesManager sites={rows} templates={templates} baseDomain={BASE_DOMAIN} />
    </>
  );
}

