import { test } from "node:test";
import assert from "node:assert/strict";
import {
  sanitizeSlug,
  isValidSlug,
  pageFilePath,
  escapeHtml,
  renderPage,
  renderSite,
  isSiteDocument,
  type SiteDocument,
} from "../lib/site-render.ts";

/**
 * Unit tests for the PURE site renderer — the code that turns an editor document
 * into the exact static files written into `/var/www/<domain>`. It has no IO, so
 * every guarantee the publish pipeline relies on can be asserted directly here.
 */

test("sanitizeSlug lowercases, hyphenates, and trims to a valid DNS label", () => {
  assert.equal(sanitizeSlug("My Cafe!"), "my-cafe");
  assert.equal(sanitizeSlug("  Hello   World  "), "hello-world");
  assert.equal(sanitizeSlug("--Leading.and.Trailing--"), "leading-and-trailing");
  assert.equal(sanitizeSlug("café"), "cafe"); // NFKD strips the accent
  assert.equal(sanitizeSlug("!!!"), ""); // nothing usable -> empty (caller must fall back)
  // A 63-char cap that lands on a hyphen must not leave a trailing hyphen.
  const long = sanitizeSlug("a".repeat(62) + " b");
  assert.ok(isValidSlug(long), `expected a valid label, got ${long}`);
  assert.ok(!long.endsWith("-"));
});

test("isValidSlug accepts DNS labels and rejects everything else", () => {
  assert.ok(isValidSlug("my-site"));
  assert.ok(isValidSlug("a"));
  assert.ok(!isValidSlug("-lead"));
  assert.ok(!isValidSlug("trail-"));
  assert.ok(!isValidSlug("has space"));
  assert.ok(!isValidSlug("UPPER"));
  assert.ok(!isValidSlug(""));
  assert.ok(!isValidSlug(42 as unknown));
});

test("pageFilePath maps routes to clean-URL files", () => {
  assert.equal(pageFilePath("/"), "index.html");
  assert.equal(pageFilePath("/about"), "about/index.html");
  assert.equal(pageFilePath("/About Us"), "about-us/index.html");
  assert.equal(pageFilePath("/blog/hello"), "blog/hello/index.html");
  assert.equal(pageFilePath(""), "index.html");
});

test("escapeHtml neutralises markup-significant characters", () => {
  assert.equal(escapeHtml(`<script>"&'`), "&lt;script&gt;&quot;&amp;&#39;");
});

test("renderPage produces a self-contained document with inlined CSS", () => {
  const html = renderPage({
    path: "/",
    title: "Hi <there>",
    seoDesc: 'A "great" site',
    html: "<h1>Hello</h1>",
    css: ".x{color:red}",
  });
  assert.ok(html.startsWith("<!doctype html>"));
  assert.ok(html.includes('<meta name="viewport"'), "must be mobile-responsive");
  assert.ok(html.includes("<title>Hi &lt;there&gt;</title>"), "title must be escaped");
  assert.ok(html.includes('content="A &quot;great&quot; site"'), "seo desc must be escaped");
  assert.ok(html.includes(".x{color:red}"), "css must be inlined");
  assert.ok(html.includes("<h1>Hello</h1>"), "body html must be present");
  // No external requests — the whole point of a static bundle.
  assert.ok(!/<link[^>]+href=/.test(html));
});

test("renderSite emits one file per page and requires a home page", () => {
  const doc: SiteDocument = {
    pages: [
      { path: "/", title: "Home", html: "<h1>H</h1>", css: "" },
      { path: "/about", title: "About", html: "<h1>A</h1>", css: "" },
    ],
  };
  const files = renderSite(doc, { siteName: "Test" });
  const names = files.map((f) => f.file).sort();
  assert.deepEqual(names, ["about/index.html", "index.html"]);
});

test("renderSite refuses an empty document rather than swap an empty dir over a live site", () => {
  assert.throws(() => renderSite({ pages: [] }), /Nothing to publish/);
  assert.throws(
    () => renderSite({ pages: [{ path: "/only-sub", html: "", css: "" }] }),
    /home page/,
    "a site with no home page must fail loudly"
  );
});

test("renderSite rejects two pages that collide to the same file", () => {
  assert.throws(
    () =>
      renderSite({
        pages: [
          { path: "/", html: "", css: "" },
          { path: "//", html: "", css: "" },
        ],
      }),
    /same file/
  );
});

test("isSiteDocument validates the wire shape used by saveDraft", () => {
  assert.ok(isSiteDocument({ pages: [{ path: "/", html: "", css: "" }] }));
  assert.ok(!isSiteDocument(null));
  assert.ok(!isSiteDocument({ pages: "nope" }));
  assert.ok(!isSiteDocument({ pages: [{ path: "no-leading-slash", html: "", css: "" }] }));
  assert.ok(!isSiteDocument({ pages: [{ path: "/", html: 1, css: "" }] }));
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { stripComments, stripCommentsAndStrings } from "./_source-tools.ts";

/**
 * Structural guards over the Website Builder server actions + publish worker.
 *
 * `lib/actions-sites.ts` is a `"use server"` module, so EVERY export is a public
 * network endpoint reachable by a stranger with curl. These tripwires assert, in
 * executable code (comments AND string contents stripped first, so a mention in
 * an error message or a doc comment can never satisfy them), that:
 *   - every exported action authenticates and ownership-checks; and
 *   - the publish worker keeps the honesty invariant — it renders before writing,
 *     gates real infra behind ENABLE_REAL_PUBLISH, refuses to fake success on a
 *     prod box with the flag off, and reloads behind the `nginx -t` gate.
 */

const ROOT = join(import.meta.dirname, "..");

/** Read + strip comments AND string/template contents — assertions are about code SHAPE. */
function shape(rel: string): string {
  return stripCommentsAndStrings(readFileSync(join(ROOT, rel), "utf8"));
}
/** Read + strip comments only (keeps literals) — for the `"use server"` check. */
function withStrings(rel: string): string {
  return stripComments(readFileSync(join(ROOT, rel), "utf8"));
}
/** Collapse whitespace so substring checks are insensitive to formatting. */
function dense(s: string): string {
  return s.replace(/\s+/g, "");
}

/** Every `export async function NAME` in a (stripped) module. */
function exportedActions(src: string): string[] {
  return [...src.matchAll(/export\s+async\s+function\s+([A-Za-z0-9_$]+)\s*\(/g)].map((m) => m[1]);
}

/** The body of `export async function NAME`, by brace matching (strings already blanked). */
function bodyOf(src: string, name: string): string {
  const decl = new RegExp(`export\\s+async\\s+function\\s+${name}\\s*\\(`).exec(src);
  assert.ok(decl, `expected an exported action named ${name}`);
  // Skip the parameter list.
  let i = src.indexOf("(", decl.index);
  let parens = 0;
  for (; i < src.length; i++) {
    if (src[i] === "(") parens++;
    else if (src[i] === ")" && --parens === 0) break;
  }
  // Skip a return-type annotation's braces (Promise<{...}>) via angle tracking.
  let angles = 0;
  for (i++; i < src.length; i++) {
    const c = src[i];
    if (c === "<") angles++;
    else if (c === ">") angles = Math.max(0, angles - 1);
    else if (c === "{" && angles === 0) break;
  }
  const start = i;
  let depth = 0;
  for (; i < src.length; i++) {
    if (src[i] === "{") depth++;
    else if (src[i] === "}" && --depth === 0) return src.slice(start, i + 1);
  }
  assert.fail(`unbalanced body for ${name}`);
}

const ACTIONS = "lib/actions-sites.ts";
const WORKER = "worker/site-publish.ts";

/** Markers that establish + prove WHO is asking for a Site action. */
const AUTH_MARKERS = ["requireUser(", "ownedSite("];

test("actions-sites declares \"use server\"", () => {
  assert.ok(withStrings(ACTIONS).includes('"use server"'));
});

test("every exported site action authenticates its caller", () => {
  const src = shape(ACTIONS);
  const names = exportedActions(src);
  // Sanity: the module really exposes the actions we think it does.
  for (const expected of [
    "listSites",
    "createSite",
    "getSiteForEdit",
    "saveDraft",
    "renameSite",
    "publishSite",
    "unpublishSite",
    "deleteSite",
  ]) {
    assert.ok(names.includes(expected), `expected action ${expected} to exist`);
  }
  const unguarded = names.filter((n) => {
    const body = bodyOf(src, n);
    return !AUTH_MARKERS.some((m) => body.includes(m));
  });
  assert.deepEqual(unguarded, [], "these actions are reachable anonymously with no identity check");
});

test("ownedSite authenticates and proves ownership by userId", () => {
  const src = shape(ACTIONS);
  const helper = /async\s+function\s+ownedSite\s*\(/.exec(src);
  assert.ok(helper, "ownedSite helper must exist");
  // Grab from the helper decl to a reasonable slice; it is small.
  const body = src.slice(helper.index, helper.index + 600);
  assert.ok(body.includes("requireUser("), "ownedSite must call requireUser()");
  assert.ok(
    dense(body).includes("site.userId!==user.id"),
    "ownedSite must reject a Site the caller does not own"
  );
});

test("every mutating action goes through the ownership choke point (ownedSite)", () => {
  const src = shape(ACTIONS);
  for (const n of ["saveDraft", "publishSite", "unpublishSite", "deleteSite", "renameSite", "getSiteForEdit"]) {
    assert.ok(bodyOf(src, n).includes("ownedSite("), `${n} must ownership-check via ownedSite`);
  }
});

test("only the worker enqueues jobs / actions never touch shell helpers directly", () => {
  const src = shape(ACTIONS);
  // Real infra work belongs in the worker; the action module must not import the
  // SSH layer. (A regression that imported ssh-exec here would move privileged
  // work onto the request path.)
  assert.ok(!src.includes("ssh-exec"), "actions must not touch the SSH layer directly");
  assert.ok(!src.includes("withServerSsh"), "actions must not open SSH connections");
});

/* --------------------------- publish worker honesty --------------------------- */

test("worker gates real publishing behind ENABLE_REAL_PUBLISH and SANDBOX", () => {
  const src = shape(WORKER);
  assert.ok(src.includes("ENABLE_REAL_PUBLISH"), "REAL must be derived from ENABLE_REAL_PUBLISH");
  // REAL must require NOT sandbox — the same belt-and-suspenders as websites.ts.
  assert.ok(dense(src).includes("!SANDBOX&&process.env.ENABLE_REAL_PUBLISH"), "REAL = !SANDBOX && flag");
});

test("worker refuses to fake success on a prod box with the flag off", () => {
  const src = dense(shape(WORKER));
  // Both handlers must carry the `!REAL && !SANDBOX -> throw` guard, so a prod box
  // that lost the flag never writes PUBLISHED having touched nothing.
  const guards = src.split("!REAL&&!SANDBOX").length - 1;
  assert.ok(guards >= 2, `expected the honesty guard in both handlers, found ${guards}`);
});

test("worker renders BEFORE writing and checks exit codes + the nginx -t gate", () => {
  const src = shape(WORKER);
  assert.ok(src.includes("renderSite("), "must render the bundle (pure) before publishing");
  assert.ok(src.includes("assertDomain("), "the publish domain must be allowlist-validated");
  assert.ok(src.includes("assertPath("), "the doc root / release path must be allowlist-validated");
  assert.ok(src.includes("assertOk("), "remote command exit codes must be checked");
  assert.ok(src.includes("reloadNginx("), "reload must go through the nginx -t gate");
  assert.ok(src.includes("verifyServing("), "a real publish must be proven to serve");
});

test("worker publish is atomic — build a release dir then swap with mv", () => {
  const src = dense(shape(WORKER));
  // A per-job release dir is built in full, then moved into place; a failure
  // before the swap leaves the live docRoot untouched.
  assert.ok(src.includes(".rel-"), "must build into a per-job release directory");
  assert.ok(src.includes("mv"), "must swap the release into place with mv (a rename)");
});

